// Crusaders Mainframe — turning scanner bytes into one complete code.
//
// WHY THIS EXISTS
// ---------------
// hal::IScannerPort hands over whatever bytes have arrived and never blocks,
// because the loop that would be blocked is the same loop that services the
// relay auto-off timer. Line assembly therefore happens above the port, where a
// partial code is just state and the host suite can feed it in pieces.
//
// The wire is a 9600 baud TTL line running beside four switching relay coils.
// Truncated payloads, split lines and dropped terminators are ordinary service,
// not a thought experiment, so every one of them has a defined outcome here.
//
// WHY AN OVER-LONG CODE IS REFUSED AND AN LCD LINE IS TRUNCATED
// -------------------------------------------------------------
// The LCD is 16 columns, so text that does not fit was going to be cut anyway
// and truncating it loses nothing a player would have seen. A member code is
// the opposite: a truncated code does not fail, it identifies a DIFFERENT
// member, and the ledger debit lands on them. So an over-long code poisons the
// line and the whole thing is dropped at the terminator.
//
// WHY A CONTROL BYTE POISONS THE LINE
// -----------------------------------
// hal/Scanner.h is explicit that the stream is binary-clean and that NUL is a
// legal byte the port must deliver — deciding what a NUL MEANS is this layer's
// job, and the answer is that the payload is corrupt. The same goes for every
// other byte below 0x20: the scanner is configured to emit printable ASCII
// terminated by \r or \n, so anything else in the middle of a code is line
// noise from the relay coils. Guessing at it would put a wrong member code into
// a `!SCAN` frame, which is the one failure mode this class must not have.
//
// No Arduino headers, no heap, no String/std::string/std::vector.

#ifndef CRUSADERS_COURTLOGIC_SCANASSEMBLER_H
#define CRUSADERS_COURTLOGIC_SCANASSEMBLER_H

#include <stdint.h>

#include "../protocol/Protocol.h"

namespace courtlogic {

/// Longest code that can reach a `!SCAN` frame. Taken from the protocol's
/// argument bound rather than restated, so a change there cannot leave this
/// class accepting codes the encoder will then refuse.
inline constexpr uint8_t kMaxScanLen = static_cast<uint8_t>(proto::kMaxArgLen);

/// At the idle gap (`!CFG,SGAP`, default 150 ms) a partial line this long or
/// longer is a scan — a scanner configured with no suffix still works (HW-5) —
/// and anything shorter is discarded, so one stray byte is never glued onto
/// the next member's code (FWM-14). A member code is 19 characters.
inline constexpr uint8_t kGapScanMinLen = 8U;

/// Why a line was dropped. Reported so a court whose scanner cable is failing
/// looks different from a court nobody is using.
enum class ScanReject : uint8_t {
  None = 0,
  TooLong, ///< More than kMaxScanLen payload bytes before the terminator.
  Corrupt, ///< A control byte, including NUL, inside the payload.
};

class ScanAssembler {
public:
  ScanAssembler();

  /// Feed one byte from the port. True when a complete, non-empty, clean code
  /// is now available from code(); it stays valid until the first byte of the
  /// NEXT code arrives, so a caller may finish the pass it is in before reading
  /// it rather than having to copy it out immediately.
  ///
  /// `\r`, `\n` and `\r\n` all terminate one line. An empty line — which is
  /// what a lone terminator or the `\n` of a `\r\n` produces — is not an event:
  /// the scanner emits them between reads and reporting them as scans would put
  /// an empty `!SCAN` on the wire several times a session.
  bool feed(uint8_t byte);

  /// The last complete code. NUL-terminated, never null, "" until one arrives.
  const char* code() const { return buf_; }

  uint8_t length() const { return len_; }

  /// Abandon any partial line. Used on `!RST`: there is no way to know where a
  /// half-received code was going, and finishing it later with bytes from the
  /// next member's scan is worse than losing both.
  void reset();

  /// A line is part-way assembled.
  bool partial() const { return !holding_ && (len_ > 0U || poisoned_); }

  /// The scanner has been idle for the gap (v3 rule 6). With `suffixOnly`
  /// false a clean partial line of at least kGapScanMinLen characters becomes
  /// a scan (returns true, read code()); every other partial line is
  /// discarded. With `suffixOnly` (`SSUF` 1) the gap only discards.
  bool gap(bool suffixOnly);

  /// True once after a line ended (by terminator or gap) that held a byte no
  /// scanner sends at the right baud — the scanner's auto-detect counts these
  /// (HW-5). A clean line clears the count it feeds.
  bool takeGarbage() {
    const bool g = garbage_;
    garbage_ = false;
    return g;
  }

  /// Why the last dropped line was dropped, ScanReject::None if none has been.
  ScanReject lastReject() const { return lastReject_; }

  uint16_t rejectedLines() const { return rejected_; }

private:
  bool endLine();

  void reject(ScanReject why);

  char buf_[kMaxScanLen + 1];
  uint8_t len_;
  bool poisoned_;
  bool lastWasCr_;
  /// A completed code is sitting in buf_ and must survive until the next code
  /// actually starts. Without it the buffer would be one shared cell that the
  /// terminator of a CRLF, or a stray blank line, silently emptied.
  bool holding_;
  bool garbage_;
  ScanReject lastReject_;
  uint16_t rejected_;
};

} // namespace courtlogic

#endif // CRUSADERS_COURTLOGIC_SCANASSEMBLER_H
